'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import type { ComponentProps, ReactNode } from 'react'

type NativeViewTransition = {
  finished: Promise<void>
  skipTransition: () => void
}

type ViewTransitionDocument = Document & {
  startViewTransition?: (
    update: () => void | Promise<void>,
  ) => NativeViewTransition
}

type TransitionLinkProps = Omit<
  ComponentProps<typeof Link>,
  'children' | 'href' | 'onNavigate' | 'transitionTypes'
> & {
  children: ReactNode
  direction: 'forward' | 'back'
  href: string
  productSlug: string
}

let activeTransition: NativeViewTransition | undefined

function getProductImage(slug: string) {
  return document.querySelector<HTMLElement>(
    `[data-product-image="${CSS.escape(slug)}"]`,
  )
}

function waitForDestination(
  href: string,
  direction: TransitionLinkProps['direction'],
  productSlug: string,
) {
  const destination = new URL(href, window.location.href)
  const pageSelector =
    direction === 'forward' ? '[data-page="product"]' : '[data-page="gallery"]'

  return new Promise<HTMLElement | null>((resolve) => {
    const startedAt = performance.now()

    function checkDestination() {
      const productImage = getProductImage(productSlug)
      const routeIsReady =
        window.location.pathname === destination.pathname &&
        document.querySelector(pageSelector)

      if (routeIsReady) {
        resolve(productImage)
        return
      }

      // Do not hold the browser's transition indefinitely if a navigation fails.
      if (performance.now() - startedAt > 8000) {
        resolve(null)
        return
      }

      requestAnimationFrame(checkDestination)
    }

    checkDestination()
  })
}

export function TransitionLink({
  children,
  direction,
  href,
  productSlug,
  ...props
}: TransitionLinkProps) {
  const router = useRouter()

  return (
    <Link
      {...props}
      href={href}
      onNavigate={(event) => {
        event.preventDefault()

        const viewTransitionDocument = document as ViewTransitionDocument
        const reduceMotion = window.matchMedia(
          '(prefers-reduced-motion: reduce)',
        ).matches

        if (!viewTransitionDocument.startViewTransition || reduceMotion) {
          router.push(href)
          return
        }

        activeTransition?.skipTransition()

        const root = document.documentElement
        root.dataset.transitionDirection = direction
        const sourceImage = getProductImage(productSlug)
        sourceImage?.style.setProperty('view-transition-name', 'product-image')

        const transition = viewTransitionDocument.startViewTransition(
          async () => {
            router.push(href)
            const destinationImage = await waitForDestination(
              href,
              direction,
              productSlug,
            )
            destinationImage?.style.setProperty(
              'view-transition-name',
              'product-image',
            )
          },
        )

        activeTransition = transition
        transition.finished.finally(() => {
          sourceImage?.style.removeProperty('view-transition-name')
          getProductImage(productSlug)?.style.removeProperty(
            'view-transition-name',
          )
          delete root.dataset.transitionDirection

          if (activeTransition === transition) {
            activeTransition = undefined
          }
        })
      }}
    >
      {children}
    </Link>
  )
}
